    @Select("SELECT id, input_file, output_file, template_id, watermark_content, watermark_font_size, "
            + "watermark_position, status, error_message, owner_id, created_at, completed_at FROM tasks WHERE id = #{id}")
    Task findById(Long id);

    @Select("SELECT id, input_file, output_file, template_id, watermark_content, watermark_font_size, "
            + "watermark_position, status, error_message, owner_id, created_at, completed_at "
            + "FROM tasks WHERE owner_id = #{ownerId} ORDER BY created_at DESC, id DESC")
